INSERT INTO "Product" ("id", "name", "slug", "brand", "shortDescription", "description", "categoryId", "status", "price", "compareAtPrice", "costPrice", "ratingAvg", "ratingCount", "soldCount", "badges", "highlights", "specs", "care", "freeShipping", "featured", "weightGrams", "createdAt", "updatedAt") VALUES ('cmtdrx41c0034kg5k1b5klpk5', 'Aro 2-Seat Sofa', 'aro-2-seat-sofa', 'AXIARO', 'The compact Aro — same deep seat, sized for smaller rooms.', 'Everything that makes the Aro three-seater comfortable, shortened to fit a condo living room or a reading corner. Washable slipcover, feather-wrapped cushions, solid pine frame.', 'cmtdrx39k0002kg5kpjfcgg5c', 'ACTIVE', 2649000, NULL, NULL, 4.6, 142, 497, '[]', '["Removable, machine-washable slipcover","Feather-wrapped foam seats","Fits through a standard doorway","10-year frame guarantee"]', '{"Width":"168 cm","Depth":"98 cm","Height":"78 cm","Seat height":"43 cm","Frame":"Solid pine"}', 'Machine wash cover cold, tumble dry low.', true, false, 34000, '2026-07-09T02:40:52.335Z', '2026-08-29T02:40:52.656Z') ON CONFLICT DO NOTHING;
INSERT INTO "Product" ("id", "name", "slug", "brand", "shortDescription", "description", "categoryId", "status", "price", "compareAtPrice", "costPrice", "ratingAvg", "ratingCount", "soldCount", "badges", "highlights", "specs", "care", "freeShipping", "featured", "weightGrams", "createdAt", "updatedAt") VALUES ('cmtdrx474003pkg5k5uhb5kok', 'Perch Lounge Chair', 'perch-lounge-chair', 'AXIARO', 'A sculptural lounge chair with a cord-wrapped back.', 'Perch pairs a steam-bent oak frame with a hand-wrapped paper-cord back that gives just enough. The seat cushion is wool-blend and buttoned in place. Light enough to move between rooms.', 'cmtdrx3aq0008kg5k90nusoxs', 'ACTIVE', 1490000, 1790000, NULL, 4.8, 96, 336, '["sale"]', '["Steam-bent solid oak frame","Hand-wrapped paper cord back","Wool-blend seat cushion","Weighs 6.2 kg"]', '{"Width":"68 cm","Depth":"74 cm","Height":"79 cm","Seat height":"40 cm","Frame":"Solid oak"}', NULL, true, false, 6200, '2026-06-02T02:40:52.335Z', '2026-08-29T02:40:52.865Z') ON CONFLICT DO NOTHING;
INSERT INTO "Product" ("id", "name", "slug", "brand", "shortDescription", "description", "categoryId", "status", "price", "compareAtPrice", "costPrice", "ratingAvg", "ratingCount", "soldCount", "badges", "highlights", "specs", "care", "freeShipping", "featured", "weightGrams", "createdAt", "updatedAt") VALUES ('cmtdrx4bk0046kg5kk7x5rm7s', 'Linea Coffee Table', 'linea-coffee-table', 'AXIARO', 'A slim oak coffee table with a single low shelf.', 'Linea keeps a low profile: a 22 mm solid oak top, tapered legs, and one open shelf for books and remotes. Flat-packed with a five-minute assembly.', 'cmtdrx3a40004kg5kr92qossy', 'ACTIVE', 899000, NULL, NULL, 4.5, 74, 259, '[]', '["22 mm solid oak top","Lower storage shelf","Tool-light assembly","Felt floor pads included"]', '{"Width":"110 cm","Depth":"55 cm","Height":"38 cm","Material":"Solid oak, oil finish"}', 'Wipe with a damp cloth; re-oil yearly with any furniture oil.', true, false, 14000, '2026-04-26T02:40:52.335Z', '2026-08-29T02:40:53.024Z') ON CONFLICT DO NOTHING;
INSERT INTO "Product" ("id", "name", "slug", "brand", "shortDescription", "description", "categoryId", "status", "price", "compareAtPrice", "costPrice", "ratingAvg", "ratingCount", "soldCount", "badges", "highlights", "specs", "care", "freeShipping", "featured", "weightGrams", "createdAt", "updatedAt") VALUES ('cmtdrx4hf004rkg5k7jwssegt', 'Stack Bookcase', 'stack-bookcase', 'AXIARO', 'An open five-shelf bookcase you can wall-anchor.', 'A clean grid of five shelves in a powder-coated steel frame with oak-veneer boards. Anchor strap included — please use it.', 'cmtdrx3ag0006kg5kw84uent8', 'ACTIVE', 1290000, NULL, NULL, 4.4, 53, 185, '[]', '["Powder-coated steel frame","Five adjustable shelves","Wall-anchor strap included","Holds ~40 kg per shelf"]', '{"Width":"80 cm","Depth":"34 cm","Height":"180 cm","Material":"Steel + oak veneer"}', NULL, true, false, 22000, '2026-03-20T02:40:52.335Z', '2026-08-29T02:40:53.235Z') ON CONFLICT DO NOTHING;
INSERT INTO "Product" ("id", "name", "slug", "brand", "shortDescription", "description", "categoryId", "status", "price", "compareAtPrice", "costPrice", "ratingAvg", "ratingCount", "soldCount", "badges", "highlights", "specs", "care", "freeShipping", "featured", "weightGrams", "createdAt", "updatedAt") VALUES ('cmtdrx51l006fkg5kvkt09nnr', 'Hopsack Washed Cotton Duvet Set', 'hopsack-duvet-set', 'AXIARO', 'Stonewashed cotton percale that feels broken-in from night one.', 'A duvet cover and two pillowcases in 200-thread-count cotton percale, washed for softness and a lived-in crinkle. Coconut-shell buttons, generous sizing, and internal corner ties.', 'cmtdrx3c8000hkg5ki0mpc139', 'ACTIVE', 429000, NULL, NULL, 4.8, 411, 980, '[]', '["Stonewashed cotton percale","Coconut-shell button closure","Internal corner ties","OEKO-TEX certified"]', '{"Includes":"1 duvet cover, 2 pillowcases","Fabric":"100% cotton percale","Thread count":"200"}', 'Machine wash warm with like colours. Tumble dry low.', true, false, 2200, '2026-01-05T02:40:52.335Z', '2026-08-29T02:40:53.961Z') ON CONFLICT DO NOTHING;
