INSERT INTO "Product" ("id", "name", "slug", "brand", "shortDescription", "description", "categoryId", "status", "price", "compareAtPrice", "costPrice", "ratingAvg", "ratingCount", "soldCount", "badges", "highlights", "specs", "care", "freeShipping", "featured", "weightGrams", "createdAt", "updatedAt") VALUES ('cmtdrxhdd012ukg5ksex1fc32', 'Trail Water-Resistant Chelsea Boot', 'trail-chelsea-boot', 'AXIARO', 'A Chelsea boot on a lugged sole, built for wet pavements.', 'Water-resistant oiled leather, storm-welted for a tighter seal against the sole, on a cushioned lugged outsole with real grip. Elastic side panels are recycled.', 'cmtdrx3mj0028kg5kq8oys3jl', 'ACTIVE', 469000, NULL, NULL, 4.8, 342, 890, '["bestseller"]', '["Water-resistant oiled leather","Storm welt construction","Cushioned lugged outsole","Recycled elastic gussets"]', '{"Upper":"Oiled full-grain leather","Sole":"Rubber lug, Goodyear-welt-style","Fit":"True to size"}', 'Wax regularly. Dry slowly, never on a radiator. Re-welt when the tread wears.', true, true, 1200, '2026-05-12T02:40:52.335Z', '2026-08-29T12:20:42.946Z') ON CONFLICT DO NOTHING;
INSERT INTO "Product" ("id", "name", "slug", "brand", "shortDescription", "description", "categoryId", "status", "price", "compareAtPrice", "costPrice", "ratingAvg", "ratingCount", "soldCount", "badges", "highlights", "specs", "care", "freeShipping", "featured", "weightGrams", "createdAt", "updatedAt") VALUES ('cmtdrxd8i00rekg5kiboncv8d', 'Bias-Cut Cupro Midi Dress', 'bias-cut-midi-dress', 'AXIARO', 'A fluid bias-cut dress with a cowl back.', 'Cut on the bias from a cupro-blend that moves like silk and washes at home. A high scoop front, a low cowl back, and a length that lands mid-calf.', 'cmtdrx3ja001okg5krazrlpeh', 'ACTIVE', 259000, NULL, NULL, 4.5, 92, 322, '["new"]', '["Fluid cupro-viscose blend","Bias cut for movement","Cowl back","Machine washable"]', '{"Fabric":"70% cupro, 30% viscose","Length":"Midi","Lining":"Unlined"}', 'Machine wash cold in a bag. Line dry. Cool iron.', true, false, 300, '2026-08-27T00:40:52.335Z', '2026-08-29T19:40:21.106Z') ON CONFLICT DO NOTHING;
INSERT INTO "Product" ("id", "name", "slug", "brand", "shortDescription", "description", "categoryId", "status", "price", "compareAtPrice", "costPrice", "ratingAvg", "ratingCount", "soldCount", "badges", "highlights", "specs", "care", "freeShipping", "featured", "weightGrams", "createdAt", "updatedAt") VALUES ('cmtdrxfao00xskg5k48opqi4f', 'Street Low Leather Sneaker', 'street-low-sneaker', 'AXIARO', 'A clean low-top in full-grain leather on a cup sole.', 'A minimal court silhouette in supple full-grain leather, stitched — not glued — to a natural rubber cup sole, over a removable cork-latex footbed. Made in a family-run Portuguese factory.', 'cmtdrx3ly0024kg5kvztrmxqm', 'ACTIVE', 359000, 419000, NULL, 4.7, 618, 2400, '["sale","bestseller"]', '["Full-grain leather upper","Stitched natural rubber cup sole","Removable cork-latex footbed","Made in Portugal"]', '{"Upper":"Full-grain leather","Sole":"Natural rubber","Lining":"Vegetable-tanned leather","Fit":"True to size"}', 'Brush off dirt, condition the leather, air dry away from heat.', true, true, 900, '2026-07-25T02:40:52.335Z', '2026-08-29T23:26:15.209Z') ON CONFLICT DO NOTHING;
INSERT INTO "Product" ("id", "name", "slug", "brand", "shortDescription", "description", "categoryId", "status", "price", "compareAtPrice", "costPrice", "ratingAvg", "ratingCount", "soldCount", "badges", "highlights", "specs", "care", "freeShipping", "featured", "weightGrams", "createdAt", "updatedAt") VALUES ('cmtdrxbok00n4kg5k99epa17q', 'Clean-Line Heavyweight Tee', 'clean-line-tee', 'AXIARO', 'A structured 220 gsm tee that holds its shape.', 'Tubular-knit heavyweight cotton with a clean neckline that won''t roll, and a boxy, slightly cropped body. The one you reach for.', 'cmtdrx3iq001kkg5kqhcsdxvu', 'ACTIVE', 79000, NULL, NULL, 4.6, 1180, 6200, '[]', '["220 gsm tubular-knit cotton","Ribbed neck that keeps its shape","Boxy, slightly cropped","Pre-shrunk"]', '{"Fabric":"100% cotton, 220 gsm","Fit":"Boxy"}', 'Machine wash cold, tumble dry low.', false, false, 250, '2026-07-21T02:40:52.335Z', '2026-08-29T23:26:15.263Z') ON CONFLICT DO NOTHING;
INSERT INTO "Product" ("id", "name", "slug", "brand", "shortDescription", "description", "categoryId", "status", "price", "compareAtPrice", "costPrice", "ratingAvg", "ratingCount", "soldCount", "badges", "highlights", "specs", "care", "freeShipping", "featured", "weightGrams", "createdAt", "updatedAt") VALUES ('cmtdrxgha010jkg5ktq27gw3r', 'Town Leather Loafer', 'town-leather-loafer', 'AXIARO', 'A soft, unlined loafer with a flexible flat sole.', 'Hand-lasted from soft calf leather, unlined so it moulds to your foot within a week, on a thin flexible sole with a discreet rubber insert at the ball and heel.', 'cmtdrx3m80026kg5knu5jkuhq', 'ACTIVE', 389000, NULL, NULL, 4.6, 231, 808, '[]', '["Soft unlined calf leather","Hand-lasted","Flexible leather sole with rubber inserts","Resoleable"]', '{"Upper":"Calf leather","Sole":"Leather + rubber inserts","Fit":"Size down if between sizes"}', NULL, true, false, 700, '2026-06-18T02:40:52.335Z', '2026-08-29T22:40:37.254Z') ON CONFLICT DO NOTHING;
INSERT INTO "Product" ("id", "name", "slug", "brand", "shortDescription", "description", "categoryId", "status", "price", "compareAtPrice", "costPrice", "ratingAvg", "ratingCount", "soldCount", "badges", "highlights", "specs", "care", "freeShipping", "featured", "weightGrams", "createdAt", "updatedAt") VALUES ('cmtdrx9ld00j8kg5kif4gyvan', 'Everyday Organic Oxford Shirt', 'everyday-oxford-shirt', 'AXIARO', 'A soft-washed oxford in organic cotton with a relaxed collar.', 'Cut a little roomier through the body, with a soft unlined collar that sits well open or buttoned. Woven from long-staple organic cotton and garment-washed so it''s ready to wear straight away.', 'cmtdrx3iq001kkg5kqhcsdxvu', 'ACTIVE', 189000, NULL, NULL, 4.7, 903, 4100, '["bestseller"]', '["Long-staple organic cotton","Garment-washed, no shrinkage surprises","Corozo nut buttons","Relaxed fit"]', '{"Fabric":"100% organic cotton oxford","Fit":"Relaxed","Weight":"140 gsm"}', 'Machine wash cold, hang to dry, warm iron.', false, true, 350, '2025-12-07T02:40:52.335Z', '2026-08-29T22:40:37.623Z') ON CONFLICT DO NOTHING;
INSERT INTO "Product" ("id", "name", "slug", "brand", "shortDescription", "description", "categoryId", "status", "price", "compareAtPrice", "costPrice", "ratingAvg", "ratingCount", "soldCount", "badges", "highlights", "specs", "care", "freeShipping", "featured", "weightGrams", "createdAt", "updatedAt") VALUES ('cmtdrx3sh002fkg5kumz0q5fe', 'Aro 3-Seat Sofa', 'aro-3-seat-sofa', 'AXIARO', 'A deep, low three-seater with a slipcover you can actually wash.', 'Aro was drawn for long evenings — a low back, a deep seat, and feather-wrapped foam cushions that keep their shape. The cover is a heavy basketweave in a family of quiet colours, and every panel unzips for washing. Solid pine frame, corner-blocked and glued, with a 10-year frame guarantee.', 'cmtdrx39k0002kg5kpjfcgg5c', 'ACTIVE', 3299000, 3899000, NULL, 4.7, 318, 1240, '["bestseller","sale"]', '["Removable, machine-washable slipcover","Feather-wrapped high-resilience foam seats","FSC-certified solid pine frame","10-year frame guarantee"]', '{"Width":"232 cm","Depth":"98 cm","Height":"78 cm","Seat height":"43 cm","Frame":"Solid pine","Filling":"Foam + feather"}', 'Machine wash cover cold, tumble dry low, re-fit while slightly damp.', true, true, 46000, '2026-08-15T02:40:52.335Z', '2026-08-30T02:15:47.967Z') ON CONFLICT DO NOTHING;
INSERT INTO "Product" ("id", "name", "slug", "brand", "shortDescription", "description", "categoryId", "status", "price", "compareAtPrice", "costPrice", "ratingAvg", "ratingCount", "soldCount", "badges", "highlights", "specs", "care", "freeShipping", "featured", "weightGrams", "createdAt", "updatedAt") VALUES ('cmtdrxeiy00v0kg5kag66u91l', 'Carryall Waxed-Canvas Tote', 'carryall-canvas-tote', 'AXIARO', 'A structured waxed-canvas tote with a laptop sleeve and a base that stands up.', '18 oz waxed canvas over a firm base, so it stands open on the floor. Inside: a padded 14" laptop sleeve, two slip pockets and a key leash. Leather handles darken with use.', 'cmtdrx3kg001vkg5klgrpdkyn', 'ACTIVE', 219000, 259000, NULL, 4.8, 505, 2800, '["sale","bestseller"]', '["18 oz waxed cotton canvas","Padded 14\" laptop sleeve","Stands up on its own","Vegetable-tanned leather handles"]', '{"Dimensions":"38 × 34 × 13 cm","Laptop fit":"14\"","Weight":"780 g"}', 'Spot clean. Re-wax yearly with any canvas wax.', false, true, 780, '2026-02-23T02:40:52.335Z', '2026-08-29T22:33:01.812Z') ON CONFLICT DO NOTHING;
